import java.util.*;
import java.io.*;

public class Rock_Paper_Scissors {
    public static void main(String[] args) {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            int n = Integer.parseInt(br.readLine());
            long[] a = new long[3];
            long[] b = new long[3];
            String[] inputA = br.readLine().split(" ");
            String[] inputB = br.readLine().split(" ");
            for (int i = 0; i < 3; i++) {
                a[i] = Long.parseLong(inputA[i]);
            }
            for (int i = 0; i < 3; i++) {
                b[i] = Long.parseLong(inputB[i]);
            }
            long max = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            long min = 0;
            min += (a[0] > (b[0] + b[2]) ? -(b[0] + b[2]) + a[0] : 0);
            min += (a[1] > (b[0] + b[1]) ? -(b[0] + b[1]) + a[1] : 0);
            min += (a[2] > (b[1] + b[2]) ? -(b[1] + b[2]) + a[2] : 0);
            System.out.println(min + " " + max);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
